    h, w = len(g), len(g[0])
    positions = {}
    for r in range(h):
        for c in range(w):
            if g[r][c]:
                positions.setdefault(g[r][c], []).append((r, c))
    src_color, marker_color = min(positions), max(positions)
    src, marker = positions[src_color], positions[marker_color]
    sr0, sr1 = min(r for r,c in src), max(r for r,c in src)
    sc0, sc1 = min(c for r,c in src), max(c for r,c in src)
    mr0, mr1 = min(r for r,c in marker), max(r for r,c in marker)
    mc0, mc1 = min(c for r,c in marker), max(c for r,c in marker)
    marker_set = set(marker)
    # Select the direction from the source toward the marker's center.
    dr = sum(r for r,c in marker)/len(marker) - sum(r for r,c in src)/len(src)
    dc = sum(c for r,c in marker)/len(marker) - sum(c for r,c in src)/len(src)
    vertical = abs(dr) >= abs(dc)
    for r, c in marker:
        g[r][c] = 0
    if horizontal_sym:
        # Continue the reflection past the source's lower edge.
        for r, c in src:
            rr = 2 * sr1 + 1 - r
            if 0 <= rr < h:
                g[rr][c] = src_color
    else:
        # Continue toward the marker side, reflecting across the adjacent edge.
        if (mc0 + mc1) / 2 > (sc0 + sc1) / 2:  # marker to right
            for r, c in src:
                cc = 2 * sc1 + 1 - c
                if 0 <= cc < w:
                    g[r][cc] = src_color
        else:  # marker to left
            for r, c in src:
                cc = 2 * sc0 - 1 - c
                if 0 <= cc < w:
                    g[r][cc] = src_color
    return g

